"use client";

import React, {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
} from "react";

import IstatistikBandi from "@/components/layout/IstatistikBandi";
import Header from "@/components/layout/Header";
import Footer from "@/components/layout/Footer";
import GununKelimesiKart from "@/components/dictionary/GununKelimesiKart";


import KelimeKarti from "@/components/dictionary/KelimeKarti";
import KelimeDetayDrawer from "@/components/ui/KelimeDetayDrawer";
import Kaynaklar from "@/components/layout/Kaynaklar";

import type {
  AramaModu,
  GruplanmisKelime,
  DictionaryItem,
  SozlukEkraniProps,
} from "@/types/dictionary";

import type { TemaTipi } from "@/utils/helpers";
import { metneCevir } from "@/utils/helpers";

export default function SozlukEkrani({
  loading,
  searchQuery,
  setSearchQuery,
  seciliLehce,
  setSeciliLehce,
  seciliDosya,
  setSeciliDosya,
  gununKelimesi,
  filtrelenmisSonuclar,
  aktifSozlukler,
}: SozlukEkraniProps) {
  const [metinBoyutu, setMetinBoyutu] =
    useState<number>(17);

  const [karanlikMod, setKaranlikMod] =
    useState<boolean>(false);

  const [mod, setMod] =
    useState<AramaModu>("baslayan");

  const [hedefDil, setHedefDil] =
    useState<string>("tumu");

  const [goruntulenenAdet, setGoruntulenenAdet] =
    useState<number>(20);

  const [seciliKelimeGrubu, setSeciliKelimeGrubu] =
    useState<GruplanmisKelime | null>(null);

  const [kopyalandiId, setKopyalandiId] =
    useState<string | null>(null);

  const [kaynaklarAcik, setKaynaklarAcik] =
    useState<boolean>(false);

  const inputRef = useRef<HTMLInputElement>(null);

  /*
   * "/" tuşuyla arama kutusuna odaklanma
   */
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const aktifElement = document.activeElement;

      const yazimAlanindaMi =
        aktifElement?.tagName === "INPUT" ||
        aktifElement?.tagName === "TEXTAREA" ||
        aktifElement?.tagName === "SELECT" ||
        aktifElement?.getAttribute("contenteditable") ===
          "true";

      if (event.key === "/" && !yazimAlanindaMi) {
        event.preventDefault();
        inputRef.current?.focus();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener(
        "keydown",
        handleKeyDown
      );
    };
  }, []);

  /*
   * Karanlık mod
   */
  useEffect(() => {
    if (karanlikMod) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [karanlikMod]);

  /*
   * Arama veya filtre değişince listeyi başa al
   */
  useEffect(() => {
    setGoruntulenenAdet(20);
  }, [
    searchQuery,
    hedefDil,
    seciliLehce,
    seciliDosya,
    mod,
  ]);

  /*
   * Aktif tema
   */
  const aktifTema: TemaTipi = useMemo(
    () => ({
      arkaPlan: karanlikMod
        ? "#1A1614"
        : "#FDFBF7",

      kartArkaPlan: karanlikMod
        ? "#1F1A17"
        : "#FFFFFF",

      yaziAna: karanlikMod
        ? "#F4EFE6"
        : "#2C221E",

      yaziAlt: karanlikMod
        ? "#A89A8E"
        : "#8C7A6B",

      kenarlik: karanlikMod
        ? "#3D322C"
        : "#EADDC9",

      inputArkaPlan: karanlikMod
        ? "#26201D"
        : "#FAFAFA",
    }),
    [karanlikMod]
  );

  /*
   * Sonucun hedef dilini tespit eder
   */
  const hedefDilBul = useCallback(
    (
      item: DictionaryItem | Record<string, unknown>
    ): string => {
      if (!item) {
        return "diger";
      }

      const itemRecord =
        item as Record<string, unknown>;

      const metaLang = (
        itemRecord.targetLanguage ??
        itemRecord.language ??
        itemRecord.dil ??
        ""
      )
        .toString()
        .toLowerCase();

      if (metaLang.includes("tr")) {
        return "tr";
      }

      if (
        metaLang === "ar" ||
        metaLang.includes("arab")
      ) {
        return "ar";
      }

      if (
        metaLang === "en" ||
        metaLang.includes("eng")
      ) {
        return "en";
      }

      if (
        metaLang === "ru" ||
        metaLang.includes("rus")
      ) {
        return "ru";
      }

      const dosyaAdi = metneCevir(
        itemRecord.file ??
          itemRecord.kaynak_sozluk ??
          ""
      ).toLowerCase();

      if (
        dosyaAdi.includes("tur") ||
        dosyaAdi.includes("tu-")
      ) {
        return "tr";
      }

      if (
        dosyaAdi.includes("ara") ||
        dosyaAdi.includes("-ar")
      ) {
        return "ar";
      }

      if (
        dosyaAdi.includes("eng") ||
        dosyaAdi.includes("-en")
      ) {
        return "en";
      }

      if (
        dosyaAdi.includes("rus") ||
        dosyaAdi.includes("ru-")
      ) {
        return "ru";
      }

      return "diger";
    },
    []
  );

  /*
   * Sonuçları kelimeye göre gruplar
   */
  const gruplanmisSonuclar = useMemo<
    GruplanmisKelime[]
  >(() => {
    if (
      !searchQuery?.trim() ||
      !Array.isArray(filtrelenmisSonuclar) ||
      filtrelenmisSonuclar.length === 0
    ) {
      return [];
    }

    const havuz: DictionaryItem[] =
      filtrelenmisSonuclar.filter(
        (item): item is DictionaryItem => {
          return (
            item !== null &&
            typeof item === "object" &&
            ("kelime" in item ||
              "spelling" in item)
          );
        }
      );

    const hedefDileGoreFiltreli =
      hedefDil === "tumu"
        ? havuz
        : havuz.filter(
            (item) =>
              hedefDilBul(item) === hedefDil
          );

    const gruplar = new Map<
      string,
      DictionaryItem[]
    >();

    hedefDileGoreFiltreli.forEach((item) => {
      const kelimeStr = metneCevir(
        item.kelime ||
          item.spelling ||
          ""
      );

      const key = kelimeStr
        .trim()
        .toLowerCase();

      if (!key) {
        return;
      }

      if (!gruplar.has(key)) {
        gruplar.set(key, []);
      }

      gruplar.get(key)?.push(item);
    });

    return Array.from(gruplar.values()).map(
      (kaynaklar) => {
        const ilk = kaynaklar[0];

        const kelimeBaslik = metneCevir(
          ilk.kelime ||
            ilk.spelling ||
            ""
        );

        const tespitEdilenLehce = (
          ilk.dialect ||
          ilk.lehce ||
          ilk.diyalekt ||
          "BATI"
        ).toString();

        return {
          kelime: kelimeBaslik,
          dialect: tespitEdilenLehce,
          kaynaklar,

          anlamlar: kaynaklar.map((kaynak) => {
            const kaynakObj =
              kaynak as Record<string, unknown>;

            let secilenTanim = "";

            if (
              Array.isArray(kaynak.definitions) &&
              kaynak.definitions.length > 0 &&
              kaynak.definitions[0]?.meaning
            ) {
              secilenTanim = metneCevir(
                kaynak.definitions[0].meaning
              );
            } else if (
              kaynak.full_definition_in_html
            ) {
              secilenTanim = metneCevir(
                kaynak.full_definition_in_html
              );
            } else {
              secilenTanim = metneCevir(
                kaynak.tanim ||
                  kaynak.meaning ||
                  ""
              );
            }

            const ozelLehce =
              kaynakObj.dialect ||
              kaynakObj.lehce ||
              kaynakObj.diyalekt;

            return {
              tanim: secilenTanim,

              file: metneCevir(
                kaynak.file || ""
              ),

              kaynak_sozluk: metneCevir(
                kaynak.kaynak_sozluk || ""
              ),

              dialect: ozelLehce
                ? ozelLehce.toString()
                : undefined,

              language:
                typeof kaynak.language ===
                "string"
                  ? kaynak.language
                  : undefined,
            };
          }),
        };
      }
    );
  }, [
    filtrelenmisSonuclar,
    searchQuery,
    hedefDil,
    hedefDilBul,
  ]);

  /*
   * İstatistiklerde kullanılacak aktif sözlük listesi
   *
   * Bu liste;
   * - seçili dosyaya,
   * - seçili lehçeye
   * göre yeniden oluşturulur.
   */
  const istatistikSozlukleri = useMemo(() => {
    if (!Array.isArray(aktifSozlukler)) {
      return [];
    }

    const normallestir = (deger: unknown): string => {
      return String(deger ?? "")
        .trim()
        .toLocaleLowerCase("tr-TR");
    };

    const dosyaFiltresi = normallestir(seciliDosya);
    const lehceFiltresi = normallestir(seciliLehce);

    const tumDegerler = [
      "",
      "tumu",
      "tüm",
      "all",
      "hepsi",
      "tum lehceler",
      "tüm lehçeler",
    ];

    const dosyaFiltreliMi =
      !tumDegerler.includes(dosyaFiltresi);

    const lehceFiltreliMi =
      !tumDegerler.includes(lehceFiltresi);

    return aktifSozlukler.filter((sozluk) => {
      if (!sozluk || typeof sozluk !== "object") {
        return false;
      }

      const sozlukObj =
        sozluk as Record<string, unknown>;

      /*
       * Sözlüğün dosya/kaynak bilgilerinde aranacak alanlar
       */
      const kaynakDegerleri = [
        sozlukObj.file,
        sozlukObj.filename,
        sozlukObj.fileName,
        sozlukObj.kaynak_sozluk,
        sozlukObj.kaynak,
        sozlukObj.name,
        sozlukObj.ad,
        sozlukObj.id,
      ]
        .map(normallestir)
        .filter(Boolean);

      /*
       * Dosya filtresi aktifse yalnızca seçili dosyayı bırak.
       */
      if (dosyaFiltreliMi) {
        const dosyaEslesiyor = kaynakDegerleri.some(
          (kaynak) =>
            kaynak === dosyaFiltresi ||
            kaynak.includes(dosyaFiltresi) ||
            dosyaFiltresi.includes(kaynak)
        );

        if (!dosyaEslesiyor) {
          return false;
        }
      }

      /*
       * Lehçe alanları
       */
      const lehceDegerleri = [
        sozlukObj.dialect,
        sozlukObj.lehce,
        sozlukObj.diyalekt,
        sozlukObj.dialectName,
        sozlukObj.lehceAdi,
      ]
        .map(normallestir)
        .filter(Boolean);

      /*
       * Lehçe filtresi aktifse yalnızca o lehçeyi bırak.
       */
      if (lehceFiltreliMi) {
        const lehceEslesiyor = lehceDegerleri.some(
          (lehce) =>
            lehce === lehceFiltresi ||
            lehce.includes(lehceFiltresi) ||
            lehceFiltresi.includes(lehce)
        );

        if (!lehceEslesiyor) {
          return false;
        }
      }

      return true;
    });
  }, [
    aktifSozlukler,
    seciliDosya,
    seciliLehce,
  ]);

  /*
   * Bir sözlüğün kayıt/kelime sayısını bulur.
   */
  const sozlukKayitSayisiniBul = useCallback(
    (sozluk: unknown): number => {
      if (!sozluk || typeof sozluk !== "object") {
        return 0;
      }

      const sozlukObj =
        sozluk as Record<string, unknown>;

      const rawCount =
        sozlukObj.kelimeSayisi ??
        sozlukObj.kayitSayisi ??
        sozlukObj.wordCount ??
        sozlukObj.wordsCount ??
        sozlukObj.count ??
        sozlukObj.total_words ??
        sozlukObj.totalWords ??
        sozlukObj.toplamKelime ??
        0;

      /*
       * "202.425" gibi Türkçe sayı biçimlerini de destekler.
       */
      if (typeof rawCount === "string") {
        const temizSayi = rawCount
          .trim()
          .replace(/\./g, "")
          .replace(",", ".");

        const sayi = Number(temizSayi);

        return Number.isNaN(sayi) ? 0 : sayi;
      }

      const sayi = Number(rawCount);

      return Number.isNaN(sayi) ? 0 : sayi;
    },
    []
  );

  /*
   * Filtreye göre dinamik sözlük sayısı
   */
  const dinamikSozlukSayisi = useMemo<number>(() => {
    /*
     * Arama yapılıyorsa sonuçlarda görünen
     * farklı sözlükleri say.
     */
    if (searchQuery?.trim()) {
      const sozlukSeti = new Set<string>();

      gruplanmisSonuclar.forEach((grup) => {
        grup.kaynaklar?.forEach((kaynak) => {
          const kaynakAdi =
            kaynak.file ||
            kaynak.kaynak_sozluk ||
            "";

          const temizKaynakAdi =
            String(kaynakAdi).trim();

          if (temizKaynakAdi) {
            sozlukSeti.add(temizKaynakAdi);
          }
        });
      });

      return sozlukSeti.size;
    }

    /*
     * Arama yoksa filtrelenmiş sözlük listesini kullan.
     */
    if (istatistikSozlukleri.length > 0) {
      return istatistikSozlukleri.length;
    }

    return 0;
  }, [
    searchQuery,
    gruplanmisSonuclar,
    istatistikSozlukleri,
  ]);

  /*
   * Arama ve filtreye göre dinamik kelime/kayıt sayısı
   */
  const dinamikKayitSayisi = useMemo<number>(() => {
    /*
     * Arama yapılırken ekranda bulunan
     * tüm kaynak kayıtlarını say.
     */
    if (searchQuery?.trim()) {
      return gruplanmisSonuclar.reduce(
        (toplam, grup) =>
          toplam + (grup.kaynaklar?.length || 0),
        0
      );
    }

    /*
     * Arama yoksa yalnızca filtrelenmiş sözlüklerin
     * kayıt sayılarını topla.
     *
     * Böylece:
     * - Doğu seçilince Doğu toplamı,
     * - Batı seçilince Batı toplamı,
     * - Tek dosya seçilince o dosyanın sayısı,
     * - Tümü seçilince genel toplam
     * hesaplanır.
     */
    const toplam = istatistikSozlukleri.reduce(
      (genelToplam, sozluk) =>
        genelToplam +
        sozlukKayitSayisiniBul(sozluk),
      0
    );

    return toplam;
  }, [
    searchQuery,
    gruplanmisSonuclar,
    istatistikSozlukleri,
    sozlukKayitSayisiniBul,
  ]);

  /*
   * Kelime seçme
   */
  const handleKelimeSec = useCallback(
    (grup: GruplanmisKelime) => {
      setSeciliKelimeGrubu(grup);
    },
    []
  );

  /*
   * Panoya kopyalama
   */
  const handlePanoyaKopyala = useCallback(
    async (
      kelime: string,
      tanim?: string,
      id?: string
    ) => {
      const metin = `${metneCevir(
        kelime
      )}\n${metneCevir(tanim || "")}`;

      try {
        if (
          navigator.clipboard &&
          window.isSecureContext
        ) {
          await navigator.clipboard.writeText(
            metin
          );
        }

        if (id) {
          setKopyalandiId(id);

          window.setTimeout(() => {
            setKopyalandiId(null);
          }, 2000);
        }
      } catch (error) {
        console.warn(
          "Kopyalama engellendi:",
          error
        );
      }
    },
    []
  );

  /*
   * Sayfalama
   */
  const gosterilenGruplar =
    gruplanmisSonuclar.slice(
      0,
      goruntulenenAdet
    );

  const dahaFazlaVar =
    gruplanmisSonuclar.length >
    goruntulenenAdet;

  /*
   * Günün kelimesi metinleri
   */
  const gununKelimesiMetni = gununKelimesi
    ? metneCevir(
        gununKelimesi.kelime ||
          gununKelimesi.spelling ||
          ""
      )
    : "";

  const gununKelimesiTanimi = gununKelimesi
    ? metneCevir(
        gununKelimesi.tanim ||
          gununKelimesi.meaning ||
          gununKelimesi.full_definition_in_html ||
          ""
      )
    : "";

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: aktifTema.arkaPlan,
        color: aktifTema.yaziAna,
        transition: "all 0.2s ease",
        padding: "8px 14px 0 14px",
        fontFamily:
          "'IBM Plex Sans', ui-sans-serif, system-ui, -apple-system, sans-serif",
      }}
    >
      <main
        style={{
          maxWidth: "1150px",
          width: "100%",
          margin: "0 auto",
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-start",
          gap: "12px",
        }}
      >
            <Header
          karanlikMod={karanlikMod}
          toggleKaranlikMod={() =>
            setKaranlikMod((prev) => !prev)
          }
          metinBoyutu={metinBoyutu}
          setMetinBoyutu={setMetinBoyutu}
          sozlukSayisi={dinamikSozlukSayisi}
          kayitSayisi={dinamikKayitSayisi}
          tema={aktifTema}
        />

        <IstatistikBandi
          wordsCount={dinamikKayitSayisi}
          sozlukSayisi={dinamikSozlukSayisi}
          aktifTema={{
            yaziAna: aktifTema.yaziAna,
            yaziAlt: aktifTema.yaziAlt,
          }}
        />

        <SearchBox
          inputRef={inputRef}
          searchQuery={searchQuery || ""}
          setSearchQuery={setSearchQuery}
          mod={mod}
          setMod={setMod}
          hedefDil={hedefDil}
          setHedefDil={setHedefDil}
          seciliLehce={seciliLehce}
          setSeciliLehce={setSeciliLehce}
          seciliDosya={seciliDosya}
          setSeciliDosya={setSeciliDosya}
          aktifSozlukler={aktifSozlukler || []}
          setGoruntulenenAdet={setGoruntulenenAdet}
          limit={20}
        />


               {/* Günün kelimesi */}
        {!searchQuery?.trim() &&
          gununKelimesi && (
            <GununKelimesiKart
              gununKelimesi={{
                ...gununKelimesi,
                kelime: gununKelimesiMetni,
                tanim: gununKelimesiTanimi,
              }}
              karanlikMod={karanlikMod}
              metinBoyutu={metinBoyutu}
              tema={aktifTema}
              onClick={() => {
                const itemObj =
                  gununKelimesi as Record<
                    string,
                    unknown
                  >;

                const gununLehcesi = (
                  gununKelimesi.dialect ||
                  itemObj.lehce ||
                  itemObj.diyalekt ||
                  "BATI"
                ).toString();

                handleKelimeSec({
                  kelime: gununKelimesiMetni,
                  dialect: gununLehcesi,
                  kaynaklar: [gununKelimesi],
                  anlamlar: [
                    {
                      tanim: gununKelimesiTanimi,
                      file: metneCevir(
                        gununKelimesi.file || ""
                      ),
                      kaynak_sozluk: metneCevir(
                        gununKelimesi.kaynak_sozluk || ""
                      ),
                      dialect: gununLehcesi,
                    },
                  ],
                });
              }}
            />
          )}

        {/* Sonuç özeti */}
        {searchQuery?.trim() && !loading && (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "8px",
              margin: "4px 0 0 2px",
            }}
          >
            <span
              style={{
                fontSize: "11px",
                fontWeight: "bold",
                textTransform: "uppercase",
                letterSpacing: "1px",
                color: "#7A1C1C",
                backgroundColor: karanlikMod
                  ? "#2C221E"
                  : "#FDF2F2",
                padding: "2px 8px",
                borderRadius: "2px",
                border: "1px solid #F4C7C7",
              }}
            >
              SONUÇLAR
            </span>

            <p
              style={{
                fontSize: "13px",
                color: aktifTema.yaziAlt,
                margin: 0,
              }}
            >
              Toplam{" "}
              <strong
                style={{
                  color: "#7A1C1C",
                  fontWeight: "bold",
                }}
              >
                {gruplanmisSonuclar.length}
              </strong>{" "}
              kelime grubu bulundu.
            </p>
          </div>
        )}

        {/* Veri listesi / loading */}
        {loading ? (
          <div
            style={{
              textAlign: "center",
              padding: "16px 0",
              color: aktifTema.yaziAlt,
              fontSize: "14px",
              fontWeight: "bold",
            }}
          >
            📖 Sözlük koleksiyonu taranıyor...
          </div>
        ) : (
          searchQuery?.trim() && (
            <section
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "8px",
                marginBottom: "12px",
              }}
            >
              {gruplanmisSonuclar.length === 0 ? (
                <div
                  style={{
                    textAlign: "center",
                    padding: "20px 16px",
                    borderRadius: "4px",
                    border: `1px dashed ${aktifTema.kenarlik}`,
                    backgroundColor:
                      aktifTema.kartArkaPlan,
                  }}
                >
                  <p
                    style={{
                      fontSize: "15px",
                      fontWeight: "bold",
                      marginBottom: "4px",
                      color: aktifTema.yaziAna,
                    }}
                  >
                    Aradığınız kelime bulunamadı
                  </p>

                  <p
                    style={{
                      fontSize: "13px",
                      color: aktifTema.yaziAlt,
                    }}
                  >
                    &quot;{searchQuery}&quot;
                    ifadesine ait kayıt eşleşmedi.
                    Filtrelerinizi kontrol
                    edebilirsiniz.
                  </p>
                </div>
              ) : (
                gosterilenGruplar.map(
                  (grup, index) => (
                    <KelimeKarti
                      key={`${grup.kelime}-${grup.kaynaklar?.length || 0}-${index}`}
                      idx={index}
                      grup={grup}
                      tema={aktifTema}
                      metinBoyutu={metinBoyutu}
                      kopyalandiId={kopyalandiId}
                      panoyaKopyala={
                        handlePanoyaKopyala
                      }
                      onClick={handleKelimeSec}
                    />
                  )
                )
              )}

              {dahaFazlaVar && (
                <button
                  type="button"
                  onClick={() =>
                    setGoruntulenenAdet(
                      (prev) => prev + 20
                    )
                  }
                  style={{
                    marginTop: "6px",
                    width: "100%",
                    padding: "10px 14px",
                    backgroundColor: "#7A1C1C",
                    color: "#FFFFFF",
                    fontSize: "12px",
                    fontWeight: "bold",
                    borderRadius: "4px",
                    border: "none",
                    cursor: "pointer",
                    letterSpacing: "1px",
                    textTransform: "uppercase",
                  }}
                >
                  Daha Fazla Göster (
                  {gruplanmisSonuclar.length -
                    goruntulenenAdet}{" "}
                  kalan)
                </button>
              )}
            </section>
          )
        )}

        {/* Kelime detay drawer */}
        {seciliKelimeGrubu && (
          <KelimeDetayDrawer
            seciliKelime={seciliKelimeGrubu}
            kapat={() =>
              setSeciliKelimeGrubu(null)
            }
            tema={aktifTema}
            metinBoyutu={metinBoyutu}
          />
        )}

        <Footer
          aktifTema={aktifTema}
          onKaynaklarAc={() =>
            setKaynaklarAcik(true)
          }
        />

        {/* Kaynaklar modalı */}
        {kaynaklarAcik && (
          <div
            style={{
              position: "fixed",
              inset: 0,
              backgroundColor:
                "rgba(0, 0, 0, 0.6)",
              zIndex: 9999,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: "16px",
              backdropFilter: "blur(2px)",
            }}
            onClick={() =>
              setKaynaklarAcik(false)
            }
          >
            <div
              style={{
                backgroundColor:
                  aktifTema.kartArkaPlan,
                color: aktifTema.yaziAna,
                border: `1px solid ${aktifTema.kenarlik}`,
                borderRadius: "6px",
                padding: "24px",
                maxWidth: "800px",
                width: "100%",
                maxHeight: "85vh",
                overflowY: "auto",
                position: "relative",
                boxShadow:
                  "0 10px 25px rgba(0,0,0,0.2)",
              }}
              onClick={(event) =>
                event.stopPropagation()
              }
            >
              <button
                type="button"
                onClick={() =>
                  setKaynaklarAcik(false)
                }
                style={{
                  position: "absolute",
                  top: "12px",
                  right: "16px",
                  background: "none",
                  border: "none",
                  fontSize: "18px",
                  fontWeight: "bold",
                  color: "#7A1C1C",
                  cursor: "pointer",
                }}
                aria-label="Kaynaklar penceresini kapat"
              >
                ✕
              </button>

              <Kaynaklar
                tema={aktifTema}
                onClose={() =>
                  setKaynaklarAcik(false)
                }
              />
            </div>
          </div>
        )}
      </main>
    </div>
  );
}
